import {showVocabularyCard,hideVocabularyCard,wordAtTime,vocabularyCatalog} from './vocabulary_card.mjs';
export function shuffledWords(cards,rng=Math.random){const result=[...cards];for(let i=result.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
export function wrongWordIds(storage){const ids=new Set(),warnings=[];function read(key){try{return JSON.parse(storage.getItem(key)||'{}')||{};}catch{warnings.push(key);return {};}}
 for(const key of ['english-quest-school-words-v1','english-quest-7700-practice-v1'])for(const [id,r]of Object.entries(read(key)))if(r?.step===0&&r.reviews>0)ids.add(id);
 for(const [id,state]of Object.entries(read('eq_flashcards_mastery_v1')))if(state==='need_review')ids.add(id);
 for(const [id,r]of Object.entries(read('eq-mnemonics-v1').progress||{})){const records=r?.directions?Object.values(r.directions):[r];if(records.some(x=>x?.step===0&&x.reviews>0))ids.add(id);}
 return {ids,warnings};
}
export function memoryPhases(word){const r=word.repetitions;if(!r||r.length<3)throw Error('Missing repetitions');return [...r.slice(0,3).map((x,i)=>({kind:'en',round:i+1,start:x.en,end:x.zh-.2})),{kind:'wait',duration:5000},{kind:'zh',start:r[2].zh,end:word.end}];}
let pattern='normal',phases=[],phaseIndex=0,waitLeft=0,waitStarted=0;
let audio,queue=[],index=-1,word=null,epoch=0,timer=null,state='idle',label='',cache=new Map(),preparing=false;
function status(text){const el=document.querySelector('#word-queue-status');if(el)el.textContent=text;}
export function stopWordQueue(){epoch++;clearTimeout(timer);state='idle';word=null;queue=[];index=-1;audio?.pause();hideVocabularyCard();status('播放已停止。');}
function sync(){if(!word||state==='idle')return;const phase=wordAtTime([word],audio.currentTime);const step=phases[phaseIndex];showVocabularyCard({...queue[index],...word,word:word.en},{back:pattern==='memory'?step?.kind==='zh':phase?.back||false,paused:state==='paused',label:`${label} · ${index+1} / ${queue.length}${pattern==='memory'?' · '+(step?.kind==='en'?'英文 '+step.round+' / 3':step?.kind==='wait'?'回想 5 秒':'中文揭曉'):''}`,toggle:toggle,next:()=>{void playIndex(index+1);},stop:stopWordQueue});}
function schedule(){clearTimeout(timer);if(!word||state!=='playing')return;
 const step=phases[phaseIndex];if(pattern==='memory'&&step?.kind==='wait'){if(!waitStarted)waitStarted=performance.now();timer=setTimeout(()=>{waitLeft=0;void advancePhase();},Math.max(0,waitLeft-(performance.now()-waitStarted)));return;}
 if(audio.paused)return;const remaining=(pattern==='memory'?step.end:word.end)-audio.currentTime;if(remaining<=.025){if(pattern==='memory')void advancePhase();else void playIndex(index+1);return;}timer=setTimeout(schedule,Math.max(5,Math.min(40,remaining/audio.playbackRate*1000)));
}
async function advancePhase(){clearTimeout(timer);state='transition';audio.pause();phaseIndex++;if(phaseIndex>=phases.length){void playIndex(index+1);return;}const step=phases[phaseIndex];state='playing';if(step.kind==='wait'){waitLeft=step.duration;waitStarted=0;sync();schedule();return;}const token=epoch;audio.currentTime=step.start;sync();try{await audio.play();if(token===epoch)schedule();}catch{if(token===epoch){state='error';status('請重試播放。');}}}
function init(){if(audio)return;document.addEventListener('visibilitychange',()=>{if(document.hidden&&pattern==='memory'&&state==='playing'){toggle();status('記憶學習已暫停；回到畫面後按繼續。');}});audio=new Audio();audio.preload='auto';for(const ev of ['timeupdate','seeked','playing'])audio.addEventListener(ev,()=>{sync();schedule();});audio.addEventListener('pause',()=>{if(phases[phaseIndex]?.kind!=='wait')clearTimeout(timer);sync();});audio.addEventListener('ended',()=>{if(state==='playing'){if(pattern==='memory')void advancePhase();else void playIndex(index+1);}});audio.addEventListener('error',()=>{if(state==='idle')return;state='error';clearTimeout(timer);status('音檔載入失敗，請重試這張或跳到下一張。');});}
async function playIndex(next){const token=++epoch;clearTimeout(timer);state='loading';word=null;audio.pause();index=next;
 if(index>=queue.length){state='idle';hideVocabularyCard();status(`本次${label}已完成，共 ${queue.length} 張；聽完不會自動標記答對。`);return;}
 const card=queue[index];status(`${label} · ${index+1} / ${queue.length} · ${card.word}，準備中…`);
 try{let data=cache.get(card.group);if(!data){const r=await fetch(new URL(`audio/words/${card.group}.json`,import.meta.url));if(!r.ok)throw Error();data=await r.json();cache.set(card.group,data);}if(token!==epoch)return;
 word=data.words.find(w=>w.id===card.id);if(!word)throw Error();const src=new URL('audio/words/'+data.file,import.meta.url).href;
 if(audio.src!==src||audio.error){audio.src=src;await new Promise((resolve,reject)=>{const clean=()=>{audio.removeEventListener('loadedmetadata',ok);audio.removeEventListener('error',fail);clearTimeout(deadline);};const ok=()=>{clean();resolve();},fail=()=>{clean();reject(Error());};const deadline=setTimeout(fail,15000);audio.addEventListener('loadedmetadata',ok,{once:true});audio.addEventListener('error',fail,{once:true});audio.load();});}
 if(token!==epoch)return;phases=pattern==='memory'?memoryPhases(word):[];phaseIndex=0;audio.currentTime=pattern==='memory'?phases[0].start:word.start;state='playing';sync();await audio.play();if(token!==epoch)return;status(`${label} · ${index+1} / ${queue.length} · ${card.word}`);schedule();
 }catch{if(token!==epoch)return;state='error';audio.pause();status('無法播放這張，請按「繼續／重試」或「下一張」；不會自動略過。');}}
function toggle(){if(state==='error'){void playIndex(index);return;}if(!word)return;if(pattern==='memory'&&phases[phaseIndex]?.kind==='wait'){if(state==='playing'){waitLeft=Math.max(0,waitLeft-(performance.now()-waitStarted));clearTimeout(timer);waitStarted=0;state='paused';}else{state='playing';schedule();}sync();return;}if(audio.paused){const token=epoch;state='playing';audio.play().then(()=>{if(token===epoch)schedule();}).catch(()=>{if(token===epoch){state='error';status('請重試播放。');}});}else{state='paused';audio.pause();}sync();}
export async function startWordQueue(mode,{group,tier,scope='group',learning='normal',stopOther=()=>{}}){if(preparing)return;preparing=true;stopOther();init();stopWordQueue();pattern=learning==='memory'?'memory':'normal';const token=epoch;status('正在整理播放清單…');try{const cards=await vocabularyCatalog();if(token!==epoch)return;const wrong=wrongWordIds(globalThis.localStorage);let selected=mode==='wrong'?cards.filter(c=>wrong.ids.has(c.id)):cards.filter(c=>scope==='all'||(scope==='tier'?c.tier===tier:c.group===group));
 if(!selected.length&&mode==='wrong'&&wrong.warnings.length){status('部分學習紀錄無法讀取，暫時無法確認錯題；請檢查瀏覽器儲存設定。');return;}if(!selected.length){status(mode==='wrong'?'目前沒有可播放的單字錯題。請先在單字練習答題，或將閃卡標為「需複習」。':'目前範圍沒有單字。');return;}queue=mode==='random'?shuffledWords(selected):selected;label=(mode==='random'?'隨機播放':mode==='wrong'?'錯題播放':'依序播放')+(pattern==='memory'?'・記憶學習':'');await playIndex(0);
 }catch{status('無法讀取播放清單，請重試。');}finally{preparing=false;}}
export function handleQueueControl(action){if(action==='stop')stopWordQueue();if(action==='toggle')toggle();if(action==='next'&&queue.length&&index<queue.length)void playIndex(index+1);}
